tasks.solution:
```cpp
#include <cstddef>
#include <stdexcept>
#include <string>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : buf_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }
    void push(const T& x) {
        buf_[head_] = x;
        head_ = (head_ + 1) % buf_.size();
        if (count_ < buf_.size()) ++count_;
    }
    std::size_t size() const { return count_; }
    bool full() const { return count_ == buf_.size(); }
    const T& operator[](std::size_t i) const {
        if (i >= count_) throw std::out_of_range("index");
        std::size_t oldest = (head_ + buf_.size() - count_) % buf_.size();
        return buf_[(oldest + i) % buf_.size()];
    }
private:
    std::vector<T> buf_;
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<int> r(2);
    r.push(1); r.push(2); r.push(3);
    return r[0] == 2 ? 0 : 1;
}
```
The invariant is `count_ <= capacity`, and `head_` always points at the slot to overwrite next. Everything else is arithmetic modulo the capacity.

