```cpp
#include <string>
#include <string_view>
#include <vector>

std::vector<std::string> split(std::string_view s, char sep) {
    std::vector<std::string> out;
    std::size_t start = 0;
    while (true) {
        std::size_t pos = s.find(sep, start);
        if (pos == std::string_view::npos) {
            out.emplace_back(s.substr(start));
            return out;
        }
        out.emplace_back(s.substr(start, pos - start));
        start = pos + 1;
    }
}

int main() { return split("a,b", ',').size() == 2 ? 0 : 1; }
```
Views would point into the caller's buffer. If the caller passed a temporary `std::string` (for example a line just read from a file), every returned view would dangle the moment that temporary died.

