```python
def sift_up(a, i):
    while i > 0:
        p = (i - 1) // 2
        if a[i] >= a[p]:
            break
        a[i], a[p] = a[p], a[i]
        i = p

def sift_down(a, i, n):
    while True:
        smallest = i
        for c in (2 * i + 1, 2 * i + 2):
            if c < n and a[c] < a[smallest]:
                smallest = c
        if smallest == i:
            return
        a[i], a[smallest] = a[smallest], a[i]
        i = smallest

class MinHeap:
    def __init__(self):
        self.a = []

    def __len__(self):
        return len(self.a)

    def peek(self):
        if not self.a:
            raise IndexError("peek from empty heap")
        return self.a[0]

    def push(self, x):
        self.a.append(x)
        sift_up(self.a, len(self.a) - 1)

    def pop(self):
        if not self.a:
            raise IndexError("pop from empty heap")
        top = self.a[0]
        last = self.a.pop()
        if self.a:
            self.a[0] = last
            sift_down(self.a, 0, len(self.a))
        return top

h = MinHeap()
for x in [5, 1, 4]:
    h.push(x)
assert h.pop() == 1
```

```python
def sift_down(a, i, n):
    while True:
        smallest = i
        for c in (2 * i + 1, 2 * i + 2):
            if c < n and a[c] < a[smallest]:
                smallest = c
        if smallest == i:
            return
        a[i], a[smallest] = a[smallest], a[i]
        i = smallest

# O(n): most nodes sit near the bottom and can only sift down a level or two.
# The total work n/4*1 + n/8*2 + n/16*3 + ... is at most n, unlike n pushes which cost log n each.
def heapify(a):
    for i in range(len(a) // 2 - 1, -1, -1):
        sift_down(a, i, len(a))

def is_heap(a):
    return all(a[(i - 1) // 2] <= a[i] for i in range(1, len(a)))

xs = [9, 4, 7, 1, 8, 2]
heapify(xs)
assert is_heap(xs) and xs[0] == 1
```

