The real `main` is then four lines: build `args` from `argv`, open an `std::ifstream` if a path was given (or use `std::cin`), and `return run(args, file, std::cout, std::cerr);`.

```cpp
#include <algorithm>
#include <iostream>
#include <optional>
#include <sstream>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

struct Options { int column = 1; bool skip_header = false; std::string path; };

int to_int_strict(const std::string& s) {
    std::size_t pos = 0;
    int v = std::stoi(s, &pos);
    if (pos != s.size()) throw std::invalid_argument("not an integer: " + s);
    return v;
}

Options parse_args(const std::vector<std::string>& args) {
    Options o;
    for (std::size_t i = 0; i < args.size(); ++i) {
        const std::string& a = args[i];
        if (a == "--column") {
            if (i + 1 >= args.size()) throw std::invalid_argument("--column needs a value");
            o.column = to_int_strict(args[++i]);
            if (o.column < 0) throw std::invalid_argument("--column must be >= 0");
        } else if (a == "--skip-header") {
            o.skip_header = true;
        } else if (!a.empty() && a[0] == '-') {
            throw std::invalid_argument("unknown option " + a);
        } else if (o.path.empty()) {
            o.path = a;
        } else {
            throw std::invalid_argument("only one file allowed");
        }
    }
    return o;
}

std::optional<double> field_as_double(std::string_view line, int column) {
    if (!line.empty() && line.back() == '\r') line.remove_suffix(1);
    std::size_t start = 0;
    for (int c = 0; c < column; ++c) {
        std::size_t comma = line.find(',', start);
        if (comma == std::string_view::npos) return std::nullopt;
        start = comma + 1;
    }
    std::size_t end = line.find(',', start);
    std::string field(line.substr(start, end == std::string_view::npos ? std::string_view::npos : end - start));
    if (field.empty()) return std::nullopt;
    try {
        std::size_t pos = 0;
        double v = std::stod(field, &pos);
        if (pos != field.size()) return std::nullopt;
        return v;
    } catch (const std::exception&) {
        return std::nullopt;
    }
}

struct Stats { long count = 0; long skipped = 0; double min = 0, max = 0, mean = 0; };

Stats summarize(std::istream& in, int column, bool skip_header) {
    Stats s;
    double sum = 0;
    std::string line;
    bool first = true;
    while (std::getline(in, line)) {
        if (first && skip_header) { first = false; continue; }
        first = false;
        auto v = field_as_double(line, column);
        if (!v) { ++s.skipped; continue; }
        if (s.count == 0) s.min = s.max = *v;
        s.min = std::min(s.min, *v);
        s.max = std::max(s.max, *v);
        sum += *v;
        ++s.count;
    }
    if (s.count > 0) s.mean = sum / s.count;
    return s;
}

int run(const std::vector<std::string>& args, std::istream& in, std::ostream& out, std::ostream& err) {
    Options o;
    try {
        o = parse_args(args);
    } catch (const std::invalid_argument& e) {
        err << "usage: logstat [--column N] [--skip-header] [FILE]\n" << e.what() << '\n';
        return 2;
    }
    Stats s = summarize(in, o.column, o.skip_header);
    if (s.count == 0) {
        err << "no numeric values in column " << o.column << '\n';
        return 1;
    }
    out << "count=" << s.count << " skipped=" << s.skipped << " min=" << s.min
        << " max=" << s.max << " mean=" << s.mean << '\n';
    return 0;
}

int main() {
    std::istringstream in("0,4\n2,8\n");
    return run({"--column", "1"}, in, std::cout, std::cerr);
}
