```python
import heapq

def k_closest(points, k):
    h = []
    for x, y in points:
        heapq.heappush(h, (-(x * x + y * y), x, y))
        if len(h) > k:
            heapq.heappop(h)          # removes the farthest
    return [[x, y] for _, x, y in h]

# Sort-based: sorted(points, key=lambda p: p[0]**2 + p[1]**2)[:k] is O(n log n);
# the heap is O(n log k) and O(k) memory, better when k is much smaller than n.
assert sorted(k_closest([[1, 3], [-2, 2], [5, 1]], 2)) == [[-2, 2], [1, 3]]
```

